import unittest
from candidate import sum_to_n

class TestSumToN(unittest.TestCase):
    def test_sum_to_n_normal_case(self):
        self.assertEqual(sum_to_n(30), 465)

    def test_sum_to_n_larger_input(self):
        self.assertEqual(sum_to_n(100), 5050)

    def test_sum_to_n_small_input(self):
        self.assertEqual(sum_to_n(5), 15)

    def test_sum_to_n_edge_case(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_sum_to_n_zero_input(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_sum_to_n_negative_input(self):
        with self.assertRaises(ValueError):
            sum_to_n(-5)

    def test_sum_to_n_non_integer_input(self):
        with self.assertRaises(TypeError):
            sum_to_n(5.5)

    def test_sum_to_n_none_input(self):
        with self.assertRaises(TypeError):
            sum_to_n(None)

if __name__ == '__main__':
    unittest.main()
